commands:
echo "RUN_ID=${GITHUB_RUN_ID:-<none>} ATTEMPT=${GITHUB_RUN_ATTEMPT:-<none>} ACTIONS=${GITHUB_ACTIONS:-<none>}"
mkdir -p .prflow/tmp/review/pr-1977/${GITHUB_RUN_ID:-local}-${GITHUB_RUN_ATTEMPT:-1}
gh pr diff 1977 | awk '/^diff --git/{in_logs=/ [ab]\/\.prflow\/logs\//} !in_logs' | tee .prflow/tmp/review/pr-1977/${GITHUB_RUN_ID:-local}-${GITHUB_RUN_ATTEMPT:-1}/diff.patch | grep -c '^diff --git'
